import json
import uuid

# 記憶體中的投票資料
polls = {}


def handle(method, path, body):
    # 處理API請求
    if method == "POST" and path == "/polls":
        return create_poll(body)
    elif method == "GET" and path == "/polls":
        return get_polls()
    elif method == "GET" and path.startswith("/polls/"):
        poll_id = path.split("/")[3]
        return get_poll(poll_id)
    elif method == "POST" and path.startswith("/polls/") and path.endswith("/vote"):
        poll_id = path.split("/")[3]
        return vote(poll_id, body)
    elif method == "GET" and path.startswith("/polls/") and path.endswith("/results"):
        poll_id = path.split("/")[3]
        return get_results(poll_id)
    elif method == "PUT" and path.startswith("/polls/"):
        poll_id = path.split("/")[3]
        return update_poll(poll_id, body)
    elif method == "DELETE" and path.startswith("/polls/"):
        poll_id = path.split("/")[3]
        return delete_poll(poll_id)
    elif method == "GET" and path == "/stats":
        return get_stats()
    else:
        return 404, {"error": "未找到路由"}


def create_poll(body):
    # 解析請求體
    data = json.loads(body.decode())
    question = data.get("question")
    options = data.get("options", [])

    if not question or len(options) < 2:
        return 400, {"error": "題目和至少兩個選項是必需的"}

    # 建立新的投票
    poll_id = str(uuid.uuid4())
    polls[poll_id] = {
        "id": poll_id,
        "question": question,
        "options": [
            {"id": str(uuid.uuid4()), "text": option, "votes": 0}
            for option in options
        ],
        "totalVotes": 0
    }

    return 201, polls[poll_id]


def get_polls():
    # 取得所有投票列表
    return 200, list(polls.values())


def get_poll(poll_id):
    # 取得特定投票詳細資訊
    poll = polls.get(poll_id)
    if not poll:
        return 404, {"error": "找不到投票"}

    return 200, poll


def vote(poll_id, body):
    # 對特定投票進行投票
    poll = polls.get(poll_id)
    if not poll:
        return 404, {"error": "找不到投票"}

    data = json.loads(body.decode())
    option_id = data.get("optionId")

    if not option_id:
        return 400, {"error": "選項ID是必需的"}

    # 找到對應的選項並增加票數
    for option in poll["options"]:
        if option["id"] == option_id:
            option["votes"] += 1
            poll["totalVotes"] += 1
            return 200, {"message": "投票成功"}

    return 400, {"error": "選項不存在"}


def get_results(poll_id):
    # 取得投票結果
    poll = polls.get(poll_id)
    if not poll:
        return 404, {"error": "找不到投票"}

    return 200, poll


def update_poll(poll_id, body):
    # 更新投票
    poll = polls.get(poll_id)
    if not poll:
        return 404, {"error": "找不到投票"}

    data = json.loads(body.decode())
    question = data.get("question")
    options = data.get("options")

    if question:
        poll["question"] = question

    if options is not None:
        # 更新選項
        updated_options = []
        for option in options:
            if isinstance(option, dict) and "id" in option:
                # 已存在的選項
                existing_option = next((opt for opt in poll["options"] if opt["id"] == option["id"]), None)
                if existing_option:
                    existing_option["text"] = option["text"]
                    updated_options.append(existing_option)
            else:
                # 新增選項
                updated_options.append({"id": str(uuid.uuid4()), "text": option, "votes": 0})

        poll["options"] = updated_options

    return 200, poll


def delete_poll(poll_id):
    # 刪除投票
    if poll_id in polls:
        del polls[poll_id]
        return 200, {"message": "投票已刪除"}
    else:
        return 404, {"error": "找不到投票"}


def get_stats():
    # 取得系統統計資訊
    total_polls = len(polls)
    total_votes = sum(poll["totalVotes"] for poll in polls.values())

    return 200, {
        "totalPolls": total_polls,
        "totalVotes": total_votes
    }

