const api = {
    async get(endpoint) {
        const response = await fetch(`api/${endpoint}`);
        return response.json();
    },

    async post(endpoint, data) {
        const response = await fetch(`api/${endpoint}`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(data)
        });
        return response.json();
    },

    async put(endpoint, data) {
        const response = await fetch(`api/${endpoint}`, {
            method: 'PUT',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(data)
        });
        return response.json();
    },

    async delete(endpoint) {
        const response = await fetch(`api/${endpoint}`, {
            method: 'DELETE'
        });
        return response.json();
    }
};

let polls = [];
let currentPollId = null;

// 顯示建立投票表單
function showCreateForm() {
    document.getElementById('createForm').style.display = 'block';
    document.getElementById('pollList').style.display = 'none';
    document.getElementById('pollDetail').style.display = 'none';
    document.getElementById('resultsContainer').style.display = 'none';
}

// 顯示投票列表
function showPollList() {
    document.getElementById('createForm').style.display = 'none';
    document.getElementById('pollList').style.display = 'block';
    document.getElementById('pollDetail').style.display = 'none';
    document.getElementById('resultsContainer').style.display = 'none';
    loadPolls();
}

// 載入投票列表
async function loadPolls() {
    try {
        polls = await api.get('polls');
        const container = document.getElementById('pollsContainer');

        if (polls.length === 0) {
            container.innerHTML = '<p>目前沒有任何投票</p>';
            return;
        }

        container.innerHTML = polls.map(poll => `
            <div class="poll-item">
                <h3>${poll.question}</h3>
                <p>總票數: ${poll.totalVotes}</p>
                <button onclick="showPollDetail('${poll.id}')">查看詳細</button>
                <button onclick="deletePoll('${poll.id}')">刪除</button>
            </div>
        `).join('');
    } catch (error) {
        console.error('載入投票列表失敗:', error);
    }
}

// 顯示投票詳細資訊
async function showPollDetail(id) {
    try {
        const poll = await api.get(`polls/${id}`);
        currentPollId = id;

        document.getElementById('detailQuestion').textContent = poll.question;

        const optionsContainer = document.getElementById('voteOptions');
        optionsContainer.innerHTML = poll.options.map(option => `
            <div class="option">
                <button onclick="vote('${id}', '${option.id}')">投票</button>
                <span>${option.text}</span>
            </div>
        `).join('');

        document.getElementById('createForm').style.display = 'none';
        document.getElementById('pollList').style.display = 'none';
        document.getElementById('pollDetail').style.display = 'block';
        document.getElementById('resultsContainer').style.display = 'none';
    } catch (error) {
        console.error('載入投票詳細資訊失敗:', error);
    }
}

// 投票
async function vote(pollId, optionId) {
    try {
        await api.post(`polls/${pollId}/vote`, { optionId });
        alert('投票成功！');
        showPollDetail(pollId);
    } catch (error) {
        console.error('投票失敗:', error);
        alert('投票失敗');
    }
}

// 刪除投票
async function deletePoll(id) {
    if (!confirm('確定要刪除這個投票嗎？')) return;

    try {
        await api.delete(`polls/${id}`);
        loadPolls();
        alert('投票已刪除');
    } catch (error) {
        console.error('刪除投票失敗:', error);
        alert('刪除投票失敗');
    }
}

// 顯示結果
async function showResults() {
    if (!currentPollId) return;

    try {
        const poll = await api.get(`polls/${currentPollId}`);
        document.getElementById('resultsQuestion').textContent = poll.question;

        // 繪製長條圖
        drawChart(poll.options);

        document.getElementById('createForm').style.display = 'none';
        document.getElementById('pollList').style.display = 'none';
        document.getElementById('pollDetail').style.display = 'none';
        document.getElementById('resultsContainer').style.display = 'block';
    } catch (error) {
        console.error('載入結果失敗:', error);
    }
}

// 繪製長條圖
function drawChart(options) {
    const canvas = document.getElementById('voteChart');
    const ctx = canvas.getContext('2d');

    // 清除畫布
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 計算最大票數
    const maxVotes = Math.max(...options.map(o => o.votes), 1);

    // 繪製長條圖
    const barWidth = 30;
    const spacing = 20;
    const totalWidth = options.length * (barWidth + spacing);
    const startX = (canvas.width - totalWidth) / 2;

    options.forEach((option, index) => {
        const barHeight = (option.votes / maxVotes) * 150;
        const x = startX + index * (barWidth + spacing);
        const y = canvas.height - barHeight - 20;

        // 繪製長條
        ctx.fillStyle = '#4CAF50';
        ctx.fillRect(x, y, barWidth, barHeight);

        // 繪製選項文字
        ctx.fillStyle = '#000';
        ctx.font = '12px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(option.text, x + barWidth / 2, canvas.height - 5);

        // 繪製票數
        ctx.fillText(`${option.votes} 票`, x + barWidth / 2, y - 5);
    });
}

// 初始化頁面
function init() {
    document.getElementById('showCreateForm').addEventListener('click', showCreateForm);
    document.getElementById('showPollList').addEventListener('click', showPollList);

    // 建立投票表單處理
    const pollForm = document.getElementById('pollForm');
    pollForm.addEventListener('submit', async (e) => {
        e.preventDefault();

        const question = document.getElementById('question').value;
        const options = Array.from(document.querySelectorAll('#optionsContainer input'))
            .map(input => input.value)
            .filter(value => value.trim() !== '');

        if (options.length < 2) {
            alert('請至少輸入兩個選項');
            return;
        }

        try {
            await api.post('polls', { question, options });
            alert('投票建立成功！');
            pollForm.reset();
            showPollList();
        } catch (error) {
            console.error('建立投票失敗:', error);
            alert('建立投票失敗');
        }
    });

    // 新增選項
    document.getElementById('addOption').addEventListener('click', () => {
        const container = document.getElementById('optionsContainer');
        const optionGroup = document.createElement('div');
        optionGroup.className = 'option-group';
        optionGroup.innerHTML = `
            <input type="text" placeholder="選項${container.children.length + 1}" required>
            <button type="button" class="remove-option">刪除</button>
        `;

        container.appendChild(optionGroup);

        // 為新加入的刪除按鈕添加事件
        optionGroup.querySelector('.remove-option').addEventListener('click', () => {
            optionGroup.remove();
        });
    });

    // 刪除選項按鈕事件處理
    document.addEventListener('click', (e) => {
        if (e.target.classList.contains('remove-option')) {
            e.target.parentElement.remove();
        }
    });

    // 返回列表按鈕
    document.getElementById('backToList').addEventListener('click', showPollList);

    // 返回詳細資訊按鈕
    document.getElementById('backToDetail').addEventListener('click', () => {
        if (currentPollId) {
            showPollDetail(currentPollId);
        }
    });

    // 初始顯示投票列表
    showPollList();
}

// 當頁面載入完成後初始化
window.addEventListener('load', init);

